// Express 4 does not forward rejected promises from async route handlers.
// Wrap them so database/provider errors reach the final error middleware
// instead of leaving a request hanging or terminating the app process.
for (const method of ['get','post','put','patch','delete']) {
  const register = app[method].bind(app);
  app[method] = (route, ...handlers) => register(route, ...handlers.map(handler => {
    if (Array.isArray(handler)) return handler.map(wrapAsyncRoute);
    return wrapAsyncRoute(handler);
  }));
}
function wrapAsyncRoute(handler) {
  if (typeof handler !== 'function' || handler.constructor.name !== 'AsyncFunction') return handler;
  return function asyncRoute(req,res,next) { Promise.resolve(handler(req,res,next)).catch(next); };
}
app.get('/health', (req,res) => {
  const state = mongoose.connection.readyState;
  const ready = state === 1;
  res.status(ready ? 200 : 503).json({ ok: ready, service: 'xwadda', database: ['disconnected','connected','connecting','disconnecting'][state] || 'unknown' });
});
app.use((req,res,next) => {
  if (req.path === '/health' || req.path.startsWith('/assets/')) return next();
  if (mongoose.connection.readyState !== 1) return res.status(503).type('text').send('XWADDA is starting or reconnecting to its database. Refresh in a moment.');
  next();
});

