const viewHelpers = { escapeHtml, money, statusLabel: roomStatusLabel, roleLabel: roleName };
async function publicSellerCards(profiles) {
  return Promise.all(profiles.map(async p => {
    const completedCount = await Deal.countDocuments({ status: 'completed', $or: [{ buyerId: p.userId }, { sellerId: p.userId }] });
    return { ...p, completedCount };
  }));
}
