app.post('/deals',signedIn,checkCsrf,async(req,res)=>{try{
  const user=req.session.user,title=String(req.body.title||'').trim(),terms=String(req.body.terms||'').trim(),currency=String(req.body.currency||'KES'),role=String(req.body.role||'seller');
  if(title.length<3||title.length>160||terms.length<10||terms.length>10000||!ROLE_FIELDS[role])throw new Error('Enter a title, clear terms and choose a valid role.');
  const amountMinor=amountFromForm(String(req.body.amount||''),currency),fee=feeMinor(currency,amountMinor),[slot,nameField,nameKeyField]=ROLE_FIELDS[role];let created;
  for(let attempt=0;attempt<8&&!created;attempt++){const code=makeRoomCode();try{created=await Deal.create({publicId:crypto.randomBytes(13).toString('hex'),code,creatorId:user.id,[slot]:user.id,[nameField]:user.name,[nameKeyField]:user.name.trim().toLocaleLowerCase(),title,terms,currency,amountMinor,feeMinor:fee,status:'open',createdAt:new Date(),updatedAt:new Date()});}catch(err){if(err.code!==11000)throw err;}}
  if(!created)throw new Error('Could not create a unique room code. Please try again.');await addRoomEvent(created,user,role,`${user.name} created this room as ${roleName(role)}.`);res.redirect(`/deal/${created.code}`);
}catch(e){res.status(422).send(render('Room not created',`<h1>Room not created</h1><div class="notice">${escapeHtml(e.message)}</div><a class="button primary" href="/">Return to dashboard</a>`,req));}});
app.post('/deals/join',signedIn,roomJoinLimiter,checkCsrf,async(req,res)=>{try{
  const user=req.session.user,code=String(req.body.code||'').trim().toUpperCase(),role=String(req.body.role||''),mapping=ROLE_FIELDS[role];if(!/^[A-HJ-NP-Z2-9]{5}$/.test(code)||!mapping)throw new Error('Enter a valid five-character code and choose a role.');
  const deal=await Deal.findOne({code});if(!deal)throw new Error('That room code was not found. Check the code with the person who shared it.');if(['completed','cancelled','refunded'].includes(deal.status))throw new Error('This deal room is closed and no longer accepts participants.');
  const already=roomRole(deal,user.id);if(already)return res.redirect(`/deal/${deal.code}`);
  const occupiedNames=[deal.buyerName,deal.sellerName,deal.thirdPartyName].filter(Boolean).map(n=>n.trim().toLocaleLowerCase());if(occupiedNames.includes(user.name.trim().toLocaleLowerCase()))throw new Error('That participant name is already in this room. Ask the room owner to verify the correct account name.');
  const [slot,nameField,nameKeyField]=mapping;if(deal[slot])throw new Error(`The ${roleName(role).toLowerCase()} seat has already been claimed.`);
  const buyerPresent=Boolean(deal.buyerId)||(role==='buyer'),sellerPresent=Boolean(deal.sellerId)||(role==='seller');const nextStatus=buyerPresent&&sellerPresent?'awaiting_payment':deal.status;
  const nameKey=user.name.trim().toLocaleLowerCase(),guardNames={};for(const other of Object.keys(ROLE_FIELDS)){if(other!==role)guardNames[ROLE_FIELDS[other][2]]={$ne:nameKey};}
  const updated=await Deal.findOneAndUpdate({_id:deal._id,status:{$nin:['completed','cancelled','refunded']},[slot]:{$exists:false},buyerId:{$ne:user.id},sellerId:{$ne:user.id},thirdPartyId:{$ne:user.id},...guardNames},{$set:{[slot]:user.id,[nameField]:user.name,[nameKeyField]:nameKey,status:nextStatus,updatedAt:new Date()}},{new:true});
  if(!updated)throw new Error('That seat was just taken or this account is already in the room. Refresh and choose an open role.');
  await addRoomEvent(updated,user,role,`${user.name} joined as ${roleName(role)}.`);res.redirect(`/deal/${updated.code}`);
}catch(e){res.status(422).send(render('Unable to join room',`<h1>Unable to join room</h1><div class="notice">${escapeHtml(e.message)}</div><a class="button primary" href="/">Back to dashboard</a>`,req));}});
app.get('/deal/:code',signedIn,async(req,res)=>{const key=String(req.params.code||'').toUpperCase(),deal=await Deal.findOne({$or:[{code:key},{publicId:req.params.code}]});if(!deal)return res.status(404).send(render('Room not found','<h1>Room not found</h1><a href="/">Back to dashboard</a>',req));let role=roomRole(deal,req.session.user.id);if(!role&&req.session.user.role==='admin')role='admin';if(!role)return res.status(403).send(render('Room access required','<h1>Room access required</h1><p>Use the five-character code on your dashboard to join this room.</p><a class="button primary" href="/">Back to dashboard</a>',req));const messages=await RoomMessage.find({dealId:deal._id}).sort({createdAt:1}).limit(120).lean();return res.send(render(`Deal room ${deal.code||''}`,portal.room(deal,role,messages,res.locals.csrf,{escapeHtml,money,statusLabel:roomStatusLabel,roleLabel:roleName}),req));});
app.post('/room/:code/messages',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase()});const role=deal&&(roomRole(deal,req.session.user.id)||(req.session.user.role==='admin'?'admin':null)),body=String(req.body.body||'').trim();if(!deal||!role)return res.status(404).send('Room not found.');if(!body||body.length>2000)return res.status(422).send('Enter a message of 1 to 2,000 characters.');await RoomMessage.create({dealId:deal._id,userId:req.session.user.id,name:req.session.user.name,role,kind:'message',body});await Deal.updateOne({_id:deal._id},{$set:{updatedAt:new Date()}});res.redirect(`/deal/${deal.code}#activity`);});
app.post('/room/:code/cancel',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase()}),role=deal&&roomRole(deal,req.session.user.id);if(!deal||!['buyer','seller'].includes(role))return res.status(404).send('Room not found.');if(!['open','awaiting_payment','awaiting_seller','draft','accepted'].includes(deal.status))return res.status(409).send('A funded deal cannot be cancelled here. Request a refund review instead.');deal.status='cancelled';deal.updatedAt=new Date();await deal.save();await addRoomEvent(deal,req.session.user,role,'Room cancelled before funding.');res.redirect(`/deal/${deal.code}`);});
app.post('/room/:code/deliver',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase(),sellerId:req.session.user.id,status:'funded'});if(!deal)return res.status(409).send('Only the joined seller can mark a funded room delivered.');const note=String(req.body.note||'').trim();if(!note||note.length>1000)return res.status(422).send('Add a short delivery note.');deal.status='delivered';deal.deliveryNote=note;deal.updatedAt=new Date();await deal.save();await addRoomEvent(deal,req.session.user,'seller',`Seller submitted delivery: ${note}`);res.redirect(`/deal/${deal.code}`);});
app.post('/room/:code/release',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase(),buyerId:req.session.user.id,status:'delivered'});if(!deal)return res.status(409).send('Only the buyer can approve a delivered deal.');deal.status='release_requested';deal.updatedAt=new Date();await deal.save();await addRoomEvent(deal,req.session.user,'buyer','Buyer approved delivery and requested seller payout. XWADDA admin will record the manual payout.');res.redirect(`/deal/${deal.code}`);});
app.post('/room/:code/dispute',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase(),$or:[{buyerId:req.session.user.id},{sellerId:req.session.user.id}],status:{$in:['funded','delivered']}});if(!deal)return res.status(409).send('This room cannot be disputed at its current stage.');deal.status='disputed';deal.updatedAt=new Date();await deal.save();await addRoomEvent(deal,req.session.user,roomRole(deal,req.session.user.id),'A participant requested admin help and a refund/release review.');res.redirect(`/deal/${deal.code}`);});
app.post('/room/:code/refund-agree',signedIn,checkCsrf,async(req,res)=>{const deal=await Deal.findOne({code:String(req.params.code||'').toUpperCase(),$or:[{buyerId:req.session.user.id},{sellerId:req.session.user.id}],status:{$in:['funded','delivered','disputed','refund_requested']}});if(!deal)return res.status(409).send('Refund agreement is available only for funded deals.');const role=roomRole(deal,req.session.user.id);if(!['buyer','seller'].includes(role))return res.status(403).send('Only the buyer and seller can agree to a refund.');deal.refundAgreedBy=deal.refundAgreedBy||[];if(!deal.refundAgreedBy.some(item=>String(item.userId)===req.session.user.id))deal.refundAgreedBy.push({userId:req.session.user.id,role,at:new Date()});const buyerAgreed=deal.refundAgreedBy.some(item=>item.role==='buyer'),sellerAgreed=deal.refundAgreedBy.some(item=>item.role==='seller');if(buyerAgreed&&sellerAgreed)deal.status='refund_requested';deal.updatedAt=new Date();await deal.save();await addRoomEvent(deal,req.session.user,role,buyerAgreed&&sellerAgreed?'Both buyer and seller agreed to a refund. Refund processing is now pending.':`${roleName(role)} agreed to a refund. The other party must also agree before it can be processed.`);res.redirect(`/deal/${deal.code}`);});

app.post('/reports',signedIn,checkCsrf,async(req,res)=>{const details=String(req.body.details||'').trim(),category=String(req.body.category||'').trim();if(details.length<20||details.length>8000||category.length>100)return res.status(422).send('Please provide report details.');await SafetyReport.create({reporterId:req.session.user.id,category,details});res.redirect('/?reported=1');});
app.get('/admin/support',signedIn,adminOnly,async(req,res)=>{const tickets=await SupportTicket.find({}).sort({status:1,updatedAt:1}).limit(150).lean();const rows=tickets.map(t=>`<article class="support-ticket"><div class="support-ticket-head"><div><b>${escapeHtml(t.subject)}</b><small>${escapeHtml(t.userName)} · ${escapeHtml(t.email)}</small></div><span class="ticket-state">${escapeHtml(t.status)}</span></div><div class="support-thread">${t.messages.map(m=>`<div class="support-message ${m.senderRole==='admin'?'from-support':''}"><b>${escapeHtml(m.senderName)} · ${escapeHtml(m.senderRole)}</b><small>${new Date(m.createdAt).toLocaleString('en-KE')}</small><p>${escapeHtml(m.body)}</p></div>`).join('')}</div>${t.status!=='closed'?`<form method="post" action="/admin/support/${t._id}/reply" class="stack-form"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><label>Reply to member<textarea name="body" required minlength="2" maxlength="4000" rows="3"></textarea></label><button class="button primary">Send reply to member</button></form><form method="post" action="/admin/support/${t._id}/close"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><button class="button secondary">Close conversation</button></form>`:''}</article>`).join('')||'<p>No support conversations yet.</p>';res.send(render('Admin support inbox',`<main class="insights-page"><div class="page-title"><div><span class="eyebrow">PRIVATE MEMBER MESSAGES</span><h1>Support inbox</h1><p class="subhead">Member conversations land here. Replies appear in the member’s support page.</p></div><a class="button secondary" href="/admin">Admin dashboard</a></div><section class="support-list">${rows}</section></main>`,req));});
app.post('/admin/support/:id/reply',signedIn,adminOnly,checkCsrf,async(req,res)=>{const body=String(req.body.body||'').trim();if(body.length<2||body.length>4000)return res.status(422).send('Enter a reply between 2 and 4,000 characters.');const ticket=await SupportTicket.findById(req.params.id);if(!ticket||ticket.status==='closed')return res.status(404).send('Open support conversation not found.');ticket.messages.push({senderRole:'admin',senderId:req.session.user.id,senderName:req.session.user.name,body,createdAt:new Date()});ticket.status='responded';ticket.updatedAt=new Date();await ticket.save();await Audit.create({adminId:req.session.user.id,action:'support_reply_sent',details:{ticketId:String(ticket._id)}});res.redirect('/admin/support');});
app.post('/admin/support/:id/close',signedIn,adminOnly,checkCsrf,async(req,res)=>{const ticket=await SupportTicket.findByIdAndUpdate(req.params.id,{$set:{status:'closed',updatedAt:new Date()}},{new:true});if(!ticket)return res.status(404).send('Support conversation not found.');await Audit.create({adminId:req.session.user.id,action:'support_conversation_closed',details:{ticketId:String(ticket._id)}});res.redirect('/admin/support');});
app.get('/admin',signedIn,adminOnly,async(req,res)=>{
  const states=['open','awaiting_seller','draft','accepted','awaiting_payment','payment_review','funded','delivered','release_requested','completed','disputed','refund_requested','cancelled','refunded'];
  const selected=states.includes(String(req.query.status||''))?String(req.query.status):'';
  const dealFilter=selected?{status:selected}:{};
  const [totalDeals,totalMembers,pendingPayments,disputes,unfunded,completed,cancelled,waitingSupport,pendingReports,deals,reports,users,audits,volume]=await Promise.all([
    Deal.countDocuments({}),User.countDocuments({}),Deal.countDocuments({status:'payment_review'}),Deal.countDocuments({status:{$in:['disputed','refund_requested','release_requested']}}),Deal.countDocuments({status:{$in:['open','awaiting_seller','draft','accepted','awaiting_payment']}}),Deal.countDocuments({status:'completed'}),Deal.countDocuments({status:'cancelled'}),SupportTicket.countDocuments({status:'open'}),SafetyReport.countDocuments({status:'pending'}),Deal.find(dealFilter).sort({updatedAt:-1}).limit(75).lean(),SafetyReport.find({status:'pending'}).sort({createdAt:1}).limit(40).lean(),User.find().sort({createdAt:-1}).limit(50).lean(),Audit.find().sort({createdAt:-1}).limit(25).lean(),Deal.aggregate([{$match:{status:'completed'}},{$group:{_id:'$currency',amount:{$sum:'$amountMinor'},count:{$sum:1}}}])
  ]);
  const volumeText=volume.map(v=>`${v.count} ${escapeHtml(v._id)} completions · ${money(v._id,v.amount)}`).join(' · ')||'No completed deals recorded yet';
  const stats=[['All deals',totalDeals,'#deals'],['Members',totalMembers,'#accounts'],['Payments to verify',pendingPayments,'#deals'],['Cases needing attention',disputes,'#deals'],['Unfunded rooms',unfunded,'#deals'],['Completed',completed,'#deals'],['Cancelled',cancelled,'#deals'],['Open support',waitingSupport,'/admin/support'],['Safety reports',pendingReports,'#safety']].map(([label,value,href])=>`<a class="admin-stat" href="${href}"><span>${label}</span><b>${value}</b></a>`).join('');
  const options=states.map(s=>`<option value="${s}" ${selected===s?'selected':''}>${escapeHtml(s.replaceAll('_',' '))}</option>`).join('');
  const dealRows=deals.map(d=>`<article class="admin-record"><div class="admin-record-heading"><div><b>${escapeHtml(d.title)}</b><small>Room ${escapeHtml(d.code||d.publicId)} · ${new Date(d.updatedAt||d.createdAt).toLocaleString('en-KE')}</small></div><span class="state-pill status-${escapeHtml(d.status)}">${escapeHtml(d.status.replaceAll('_',' '))}</span></div><div class="admin-record-meta"><span>${escapeHtml(d.currency)} ${money(d.currency,d.amountMinor)}</span><span>Fee ${money(d.currency,d.feeMinor)}</span><span>Buyer ${escapeHtml(d.buyerName||'Not joined')}</span><span>Seller ${escapeHtml(d.sellerName||d.sellerEmail||'Not joined')}</span><span>Payment ref ${escapeHtml(d.paymentRef||'—')}</span></div>${d.status==='payment_review'?`<form method="post" action="/admin/deal/${encodeURIComponent(d.publicId)}/confirm" class="admin-action-form"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><label>Verification note<textarea name="note" required maxlength="1000" placeholder="Record the provider or chain check"></textarea></label><button class="button primary">Confirm verified deposit</button></form>`:''}${['funded','delivered','disputed','release_requested','refund_requested'].includes(d.status)?`<form method="post" action="/admin/deal/${encodeURIComponent(d.publicId)}/resolve" class="admin-action-form"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><label>Resolution<select name="resolution"><option value="completed">Record completed payout</option><option value="refunded" ${d.refundAgreedBy?.some(x=>x.role==='buyer')&&d.refundAgreedBy?.some(x=>x.role==='seller')?'':'disabled'}>Record agreed refund</option></select></label><label>Admin note<textarea name="note" required maxlength="1000"></textarea></label><button class="button primary">Record decision</button></form>${d.status==='refund_requested'?'<small class="admin-note">Both parties have agreed; review the payment before recording the refund.</small>':''}`:''}</article>`).join('')||'<div class="admin-empty">No deals match this filter.</div>';
  const reportRows=reports.map(r=>`<article class="admin-record"><div class="admin-record-heading"><b>${escapeHtml(r.category||'Safety report')}</b><small>${new Date(r.createdAt).toLocaleString('en-KE')}</small></div><p>${escapeHtml(r.details)}</p><form method="post" action="/admin/report/${r._id}" class="admin-inline-form"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><button class="button secondary" name="status" value="reviewed">Mark reviewed</button><button class="button secondary" name="status" value="dismissed">Dismiss report</button></form></article>`).join('')||'<div class="admin-empty">No pending reports.</div>';
  const userRows=users.map(u=>`<article class="admin-record"><div class="admin-record-heading"><div><b>${escapeHtml(u.name)}</b><small>${escapeHtml(u.email)} · joined ${new Date(u.createdAt).toLocaleDateString('en-KE')}</small></div><span>${escapeHtml(u.role)} · ${escapeHtml(u.status||'active')}</span></div><form method="post" action="/admin/user/${u._id}" class="admin-inline-form"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><select name="status"><option value="active" ${(u.status||'active')==='active'?'selected':''}>Active</option><option value="suspended" ${u.status==='suspended'?'selected':''}>Suspended</option><option value="closed" ${u.status==='closed'?'selected':''}>Closed</option></select><select name="role"><option value="user" ${u.role==='user'?'selected':''}>Member</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option></select><button class="button secondary">Save account</button></form></article>`).join('')||'<div class="admin-empty">No accounts yet.</div>';
  const auditRows=audits.map(a=>`<tr><td>${new Date(a.createdAt).toLocaleString('en-KE')}</td><td>${escapeHtml(a.action||'Admin action')}</td><td>${escapeHtml(a.adminId?String(a.adminId):'System')}</td><td>${escapeHtml(a.dealId?String(a.dealId):'—')}</td><td>${escapeHtml(JSON.stringify(a.details||{}).slice(0,260))}</td></tr>`).join('')||'<tr><td colspan="5">No admin actions recorded.</td></tr>';
  const html=`<main class="insights-page admin-panel"><div class="page-title"><div><span class="eyebrow">OPERATIONS</span><h1>Admin dashboard</h1><p class="subhead">Live totals and queues from this XWADDA database. Completed deal value: ${volumeText}.</p></div><a class="button secondary" href="/admin/support">Open support inbox · ${waitingSupport}</a></div><nav class="admin-nav"><a href="#deals">Deal operations</a><a href="#safety">Safety reports · ${pendingReports}</a><a href="#accounts">Accounts</a><a href="#audit">Audit log</a><a href="/admin/support">Support inbox</a></nav><section class="admin-stats-grid">${stats}</section><section class="admin-section" id="deals"><div class="admin-section-head"><div><span class="eyebrow">PAYMENTS & ESCROWS</span><h2>Deal operations</h2><p>Verify deposits against the payment provider or blockchain before changing a status.</p></div><form method="get" action="/admin" class="admin-filter"><label>Filter by status<select name="status"><option value="">All statuses</option>${options}</select></label><button class="button secondary">Apply</button></form></div><div class="admin-record-list">${dealRows}</div></section><section class="admin-section" id="safety"><div class="admin-section-head"><div><span class="eyebrow">MEMBER REPORTS</span><h2>Safety queue</h2><p>Review reports privately; the report is an allegation until verified.</p></div></div><div class="admin-record-list">${reportRows}</div></section><section class="admin-section" id="accounts"><div class="admin-section-head"><div><span class="eyebrow">ACCESS CONTROL</span><h2>Recent accounts</h2><p>Change member status and admin access. Your own admin role cannot be removed here.</p></div></div><div class="admin-record-list">${userRows}</div></section><section class="admin-section" id="audit"><div class="admin-section-head"><div><span class="eyebrow">ACCOUNTABILITY</span><h2>Recent admin actions</h2><p>Most recent 25 recorded actions.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Time</th><th>Action</th><th>Admin ID</th><th>Deal ID</th><th>Details</th></tr></thead><tbody>${auditRows}</tbody></table></div></section></main>`;
  res.send(render('Admin dashboard',html,req));
});
app.post('/admin/deal/:id/confirm',signedIn,adminOnly,checkCsrf,async(req,res)=>{const d=await Deal.findOne({publicId:req.params.id,status:'payment_review'});if(!d)return res.status(404).send('Payment not pending review.');d.status='funded';d.updatedAt=new Date();await d.save();await addRoomEvent(d,req.session.user,'admin','Admin confirmed the deposit after review.');await PaymentIntent.updateMany({dealId:d._id,provider:'crypto',status:'pending'},{status:'confirmed'});await Audit.create({adminId:req.session.user.id,dealId:d._id,action:'deposit_confirmed',details:{note:String(req.body.note||'').slice(0,1000),txHash:d.txHash,network:d.cryptoNetwork}});res.redirect('/admin');});
app.post('/admin/deal/:id/resolve',signedIn,adminOnly,checkCsrf,async(req,res)=>{const resolution=String(req.body.resolution);if(!['completed','refunded'].includes(resolution))return res.status(422).send('Invalid resolution.');const d=await Deal.findOne({publicId:req.params.id,status:{$in:['funded','delivered','disputed','refund_requested','release_requested']}});if(!d)return res.status(404).send('Deal not found.');if(resolution==='refunded'&&(!d.refundAgreedBy.some(item=>item.role==='buyer')||!d.refundAgreedBy.some(item=>item.role==='seller')))return res.status(409).send('Both buyer and seller must agree in the room before a refund can be recorded.');d.status=resolution;d.updatedAt=new Date();d.closedAt=new Date();await d.save();await addRoomEvent(d,req.session.user,'admin',resolution==='completed'?'Admin recorded the manual payout as completed.':'Both parties agreed; admin recorded the refund after processing.');await Audit.create({adminId:req.session.user.id,dealId:d._id,action:'manual_resolution_recorded',details:{resolution,note:String(req.body.note||'').slice(0,1000)}});res.redirect('/admin');});

app.post('/admin/report/:id',signedIn,adminOnly,checkCsrf,async(req,res)=>{const status=['reviewed','dismissed'].includes(String(req.body.status))?String(req.body.status):'reviewed';await SafetyReport.findByIdAndUpdate(req.params.id,{status});await Audit.create({adminId:req.session.user.id,action:status==='reviewed'?'safety_report_reviewed':'safety_report_dismissed',details:{reportId:req.params.id}});res.redirect('/admin#safety');});
app.post('/admin/user/:id',signedIn,adminOnly,checkCsrf,async(req,res)=>{const role=['user','admin'].includes(req.body.role)?req.body.role:'user',status=['active','suspended','closed'].includes(req.body.status)?req.body.status:'active';if(String(req.params.id)===req.session.user.id&&role!=='admin')return res.status(422).send('You cannot remove your own admin access.');await User.findByIdAndUpdate(req.params.id,{role,status});await Audit.create({adminId:req.session.user.id,action:'account_updated',details:{userId:req.params.id,role,status}});res.redirect('/admin');});

