app.get('/pay/:id',signedIn,async(req,res)=>{const d=await Deal.findOne({publicId:req.params.id,buyerId:req.session.user.id}).lean();if(!d)return res.status(404).send('Deal not found.');if(d.status!=='awaiting_payment')return res.status(409).send('Deal is not ready for payment.');const total=d.amountMinor+d.feeMinor;const html=`<h1>Pay for your deal</h1><p>${escapeHtml(d.title)}</p><p>Seller amount: <b>${money(d.currency,d.amountMinor)}</b></p><p>Escrow fee: <b>${money(d.currency,d.feeMinor)}</b></p><p>Total due: <b>${money(d.currency,total)}</b></p><p>${escapeHtml(d.terms)}</p>${d.currency==='KES'?`<button id="mpesa" class="button button-primary">Pay with M-Pesa</button><p id="paystate"></p><script src="https://pay.hashback.co.ke/hashpay.js"></script><script>const csrf=${JSON.stringify(res.locals.csrf)},deal=${JSON.stringify(d.publicId)};document.getElementById('mpesa').onclick=async()=>{let s=document.getElementById('paystate'),b=document.getElementById('mpesa');b.disabled=true;try{let r=await fetch('/create-mpesa-intent.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({deal})}),j=await r.json();if(!r.ok)throw Error(j.error);const h=HashPay.setup({account:j.account,amount:j.amount,reference:j.reference,onSuccess:async()=>{s.textContent='Payment submitted; checking confirmation…';for(let i=0;i<20;i++){await new Promise(x=>setTimeout(x,2500));let z=await(await fetch('/payment-status.php?id='+j.intent)).json();if(z.status==='confirmed'){s.textContent='Payment confirmed. Deal funded.';b.textContent='Payment confirmed';return}if(['failed','exception'].includes(z.status)){s.textContent='Payment needs support review. Do not pay again.';return}}s.textContent='Still processing; do not pay again until reconciled.'},onCancel:()=>s.textContent='Payment window closed. Do not repeat until status is checked.',onError:()=>s.textContent='Payment status uncertain; contact support.'});h.openIframe()}catch(e){s.textContent=e.message;b.disabled=false}}</script>`:`<h2>Select a USDT network</h2><div class="row"><button class="button button-outline" data-net="TRC20">USDT TRC20</button><button class="button button-outline" data-net="BEP20">USDT BEP20</button></div><div id="crypto"></div><script>const csrf=${JSON.stringify(res.locals.csrf)},deal=${JSON.stringify(d.publicId)},total=${JSON.stringify((total/100).toFixed(2))};const wallets={TRC20:{address:${JSON.stringify(process.env.TRC20_ADDRESS||'')},qr:'/assets/usdt-trc20-qr.png'},BEP20:{address:${JSON.stringify(process.env.BEP20_ADDRESS||'')},qr:'/assets/usdt-bep20-qr.png'}};document.querySelectorAll('[data-net]').forEach(b=>b.onclick=async()=>{const network=b.dataset.net.toLowerCase()==='trc20'?'tron':'bsc';let r=await fetch('/create-crypto-intent.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({deal,network})}),j=await r.json();if(!r.ok){alert(j.error);return}let w=wallets[b.dataset.net];document.getElementById('crypto').innerHTML='<p>Send exactly '+total+' USDT on '+b.dataset.net+'</p><img width="220" src="'+w.qr+'"><p><code>'+w.address+'</code></p><p>Reference: '+j.reference+'</p><form id="tx"><label>64-character transaction hash<input name="tx_hash" pattern="[a-fA-F0-9]{64}" minlength="64" maxlength="64" required></label><button class="button button-primary">Submit for review</button></form><p>The transaction is checked on-chain before the deal is marked funded.</p>';document.getElementById('tx').onsubmit=async e=>{e.preventDefault();let q=await fetch('/submit-crypto-hash.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({intent:j.intent,tx_hash:e.target.tx_hash.value})});let x=await q.json();alert(q.ok?'Transaction submitted for review.':x.error)}})</script>`}<form method="post" action="/deal/${d.publicId}/dispute"><input type="hidden" name="csrf" value="${escapeHtml(res.locals.csrf)}"><button class="button button-outline">Raise a dispute</button></form>`;res.send(render('Payment',html,req));});
app.post('/create-mpesa-intent.php',signedIn,checkCsrf,async(req,res)=>{const d=await Deal.findOne({publicId:String(req.body.deal||''),buyerId:req.session.user.id,status:'awaiting_payment'});if(!d||d.currency!=='KES')return res.status(409).json({error:'This deal is not available for M-Pesa payment.'});if(!process.env.HASHPAY_ACCOUNT_ID||!process.env.HASHPAY_WEBHOOK_SECRET)return res.status(503).json({error:'HashBack HashPay merchant credentials are not configured.'});const existing=await PaymentIntent.findOne({dealId:d._id,provider:'hashpay',status:'pending'});if(existing)return res.status(409).json({error:'A payment attempt is already pending. Do not pay again; wait or contact support.'});const cutoff=new Date(Date.now()-5*60*60*1000),now=new Date();const renewed=await Deal.findOneAndUpdate({_id:d._id,buyerId:req.session.user.id,status:'awaiting_payment',updatedAt:{$gt:cutoff}},{$set:{updatedAt:now}},{new:true});if(!renewed)return res.status(409).json({error:'This room has been inactive for five hours and is closing. Create a new room to continue.'});const reference='XW'+d.publicId.toUpperCase()+crypto.randomBytes(4).toString('hex').toUpperCase();const intent=await PaymentIntent.create({dealId:d._id,provider:'hashpay',providerReference:reference,amountMinor:d.amountMinor+d.feeMinor,currency:'KES'});res.json({intent:String(intent._id),account:process.env.HASHPAY_ACCOUNT_ID,amount:intent.amountMinor/100,reference});});
app.get('/payment-status.php',signedIn,async(req,res)=>{const p=await PaymentIntent.findById(String(req.query.id||'')).populate('dealId');if(!p||!p.dealId||String(p.dealId.buyerId)!==req.session.user.id)return res.status(404).json({error:'Payment not found.'});res.json({status:p.status});});
app.post('/create-crypto-intent.php',signedIn,checkCsrf,async(req,res)=>{const d=await Deal.findOne({publicId:String(req.body.deal||''),buyerId:req.session.user.id,status:'awaiting_payment'});const network=String(req.body.network||'');if(!d||d.currency!=='USDT'||!['tron','bsc'].includes(network))return res.status(409).json({error:'This USDT deal is not available for that network.'});let intent=await PaymentIntent.findOne({dealId:d._id,provider:'crypto',status:'pending'});if(intent&&intent.network!==network)return res.status(409).json({error:'A payment attempt exists on another network. Contact support before switching.'});if(!intent){const cutoff=new Date(Date.now()-5*60*60*1000),now=new Date();const renewed=await Deal.findOneAndUpdate({_id:d._id,buyerId:req.session.user.id,status:'awaiting_payment',updatedAt:{$gt:cutoff}},{$set:{updatedAt:now}},{new:true});if(!renewed)return res.status(409).json({error:'This room has been inactive for five hours and is closing. Create a new room to continue.'});intent=await PaymentIntent.create({dealId:d._id,provider:'crypto',providerReference:'XWCR'+d.publicId.toUpperCase()+crypto.randomBytes(3).toString('hex').toUpperCase(),network,amountMinor:d.amountMinor+d.feeMinor,currency:'USDT'});}res.json({intent:String(intent._id),reference:intent.providerReference});});
app.post('/submit-crypto-hash.php',signedIn,checkCsrf,async(req,res)=>{const hash=String(req.body.tx_hash||'').toLowerCase().trim();if(!/^[a-f0-9]{64}$/.test(hash))return res.status(422).json({error:'Enter a valid 64-character transaction hash.'});const intent=await PaymentIntent.findOne({_id:String(req.body.intent||''),provider:'crypto',status:'pending'}).populate('dealId');if(!intent||!intent.dealId||String(intent.dealId.buyerId)!==req.session.user.id||intent.dealId.status!=='awaiting_payment')return res.status(409).json({error:'This payment is no longer awaiting a transaction hash.'});const reviewDeal=await Deal.findOneAndUpdate({_id:intent.dealId._id,status:'awaiting_payment'},{$set:{txHash:hash,cryptoNetwork:intent.network==='tron'?'TRC20':'BEP20',status:'payment_review',updatedAt:new Date()}},{new:true});intent.providerPayload={customer_tx_hash:hash,submitted_at:new Date()};if(!reviewDeal){intent.status='exception';await intent.save();return res.status(409).json({error:'Room is no longer awaiting payment. Contact support immediately with your transaction hash.'});}await intent.save();res.json({ok:true});});
app.post('/hashpay-webhook.php',async(req,res)=>{const secret=process.env.HASHPAY_WEBHOOK_SECRET,account=process.env.HASHPAY_ACCOUNT_ID;if(!secret||!account)return res.status(503).send('Webhook is not configured.');const signature=String(req.get('x-hashpay-signature')||''),expected='sha256='+crypto.createHmac('sha256',secret).update(req.rawBody||'').digest('hex'),sig=Buffer.from(signature),exp=Buffer.from(expected);if(!signature||sig.length!==exp.length||!crypto.timingSafeEqual(sig,exp))return res.status(401).send('Invalid signature.');const payload=req.body||{};if(String(payload.AccountID||'')!==account)return res.status(403).send('Unexpected account.');const reference=String(payload.TransactionReference||''),txId=String(payload.TransactionID||''),event=String(payload.event||''),code=String(payload.ResponseCode||'');if(!reference||!txId||!['payment.success','payment.failed'].includes(event))return res.status(400).send('Missing payment fields.');const p=await PaymentIntent.findOne({provider:'hashpay',providerReference:reference});if(!p)return res.status(404).send('Unknown payment reference.');if(p.status!=='pending')return res.status(200).send('Already processed.');const received=Number.isFinite(Number(payload.TransactionAmount))?Math.round(Number(payload.TransactionAmount)*100):-1;const d=await Deal.findById(p.dealId);let ok=event==='payment.success'&&code==='0'&&received===p.amountMinor&&d&&d.status==='awaiting_payment';if(ok){const funded=await Deal.findOneAndUpdate({_id:d._id,status:'awaiting_payment'},{$set:{status:'funded',updatedAt:new Date()}},{new:true});ok=Boolean(funded);}p.status=ok?'confirmed':(event==='payment.success'?'exception':'failed');p.providerTransactionId=txId;p.providerPayload={event,ResponseCode:code,TransactionID:txId,TransactionAmount:payload.TransactionAmount,TransactionDate:payload.TransactionDate,TransactionReference:reference};await p.save();res.status(200).send('OK');});
// HashPay callback verification is deliberately unavailable until HashBack's exact signing format is configured.
app.post('/webhooks/hashpay',async(req,res)=>{if(!process.env.HASHPAY_WEBHOOK_SECRET)return res.status(503).send('Payment webhook is not configured.');const signature=String(req.get('x-hashback-signature')||'');const raw=JSON.stringify(req.body);const expected=crypto.createHmac('sha256',process.env.HASHPAY_WEBHOOK_SECRET).update(raw).digest('hex');if(!signature||!crypto.timingSafeEqual(Buffer.from(signature),Buffer.from(expected)))return res.status(401).send('Invalid signature.');return res.status(501).send('Configure the exact HashBack signed payload and settlement fields before accepting payment callbacks.');});

