async function connectMongoWithRetry(){
  while(mongoose.connection.readyState!==1){
    try {
      await mongoose.connect(mongoUri,{dbName:mongoDbName,serverSelectionTimeoutMS:10000,connectTimeoutMS:10000});
      console.log(`MongoDB connected to database ${mongoDbName}.`);
      if(process.env.ADMIN_EMAIL) await User.updateOne({email:process.env.ADMIN_EMAIL.toLowerCase()},{role:'admin'},{runValidators:true});
    } catch(e) {
      console.error('MongoDB is not ready. Check that MONGODB_URI uses the live MongoDB resource internal hostname (not localhost or 127.0.0.1), and that both Coolify resources share a network.');
      console.error(e && e.message ? e.message : e);
      await new Promise(resolve=>setTimeout(resolve,5000));
    }
  }
}
const AUTO_CLOSE_STATUSES=['open','awaiting_seller','draft','accepted','awaiting_payment'];
async function closeInactiveUnfundedDeals(){
  if(mongoose.connection.readyState!==1)return;
  const cutoff=new Date(Date.now()-5*60*60*1000), now=new Date();
  const candidates=await Deal.find({status:{$in:AUTO_CLOSE_STATUSES},updatedAt:{$lte:cutoff}}).select('_id code').limit(100).lean();
  for(const candidate of candidates){
    const closed=await Deal.findOneAndUpdate({_id:candidate._id,status:{$in:AUTO_CLOSE_STATUSES},updatedAt:{$lte:cutoff}},{$set:{status:'cancelled',closedAt:now,closeReason:'inactive_unfunded_timeout',updatedAt:now}},{new:true});
    if(closed){await PaymentIntent.updateMany({dealId:closed._id,status:'pending'},{$set:{status:'failed'}});await addRoomEvent(closed,null,'system','Automatically cancelled after five hours without activity. No deposit was confirmed.');}
  }
}
const server=app.listen(port,'0.0.0.0',()=>{
  console.log(`XWADDA listening on 0.0.0.0:${port}; checking MongoDB database ${mongoDbName}.`);
  connectMongoWithRetry().catch(e=>console.error('MongoDB reconnect loop stopped:',e));
});
server.on('error',error=>{console.error('HTTP server failed to listen:',error.message);process.exit(1);});
setInterval(()=>closeInactiveUnfundedDeals().catch(error=>console.error('Automatic unfunded-room cleanup failed:',error.message)),60*1000).unref();
